def _contains(self, label):
    return self.label == label or any(
        child._contains(label) for child in self.children
    )

def from_pov(self, from_node):
    if self.label == from_node:
        return Tree(self.label, list(self.children))

    for i, child in enumerate(self.children):
        if child._contains(from_node):
            new_child = child.from_pov(from_node)
            rest = self.children[:i] + self.children[i + 1:]
            new_child.children.append(Tree(self.label, rest))
            return new_child

    raise ValueError("Tree could not be reoriented")

def path_to(self, from_node, to_node):
    pov = self.from_pov(from_node)
    path = [pov.label]
    for child in pov.children:
        if child._contains(to_node):
            path.extend(child._path_to(to_node))
            return path

    raise ValueError("No path found")

def _path_to(self, to_node):
    if self.label == to_node:
        return [self.label]

    for child in self.children:
        if child._contains(to_node):
            return [self.label] + child._path_to(to_node)

    raise ValueError("No path found")

